insert into public.guardians (
  school_id,migration_key,full_name,mobile,occupation,address,city,country,nationality,
  whatsapp_number,status,legacy_payload
)
select p.school_id,src.migration_key,src.full_name,src.mobile,src.occupation,src.address,src.city,
       src.country,src.nationality,src.whatsapp_number,src.status,src.legacy_payload
from src cross join p
on conflict (school_id,migration_key) where migration_key is not null do update set
  full_name=excluded.full_name,mobile=excluded.mobile,occupation=excluded.occupation,
  address=excluded.address,city=excluded.city,country=excluded.country,
  nationality=excluded.nationality,whatsapp_number=excluded.whatsapp_number,
  status=excluded.status,legacy_payload=excluded.legacy_payload;

commit;
